/**
 * Estudo: 10 versões da tela de entrada, todas com e-mail + código + botão.
 * Rota /versoes-entrar. Só para escolher; a escolhida vira Entrar.jsx.
 */

function Campos({ escuro = false, botao = 'btn-primario', compacto = false, alinhado = 'left' }) {
  const rot = 'block text-[12px] font-extrabold uppercase tracking-[.08em] mb-1.5 ' + (escuro ? 'text-white/70' : 'text-tinta')
  const campo = escuro
    ? 'w-full bg-white/10 border-2 border-white/30 text-white placeholder:text-white/40 px-3 py-2.5 text-[15px] focus:outline-none focus:border-ambar'
    : 'campo'
  return (
    <form onSubmit={(e) => e.preventDefault()} className={'grid gap-4 ' + (compacto ? 'sm:grid-cols-[1.3fr_1fr_auto] sm:items-end' : '')}>
      <label className="block">
        <span className={rot}>E-mail</span>
        <input type="email" className={campo} placeholder="voce@exemplo.com" />
      </label>
      <label className="block">
        <span className={rot}>Código de acesso</span>
        <input inputMode="numeric" className={campo + ' !text-[20px] tracking-[.3em] display'} placeholder="••••••" />
      </label>
      <button type="submit" className={botao + (compacto ? ' !py-3' : ' w-full !py-3.5 !text-[15px]')}>Entrar</button>
      {!compacto && (
        <div className={'flex flex-wrap gap-x-4 gap-y-1 text-[13px] ' + (alinhado === 'center' ? 'justify-center' : '')}>
          <a href="#" className={'font-bold underline underline-offset-4 ' + (escuro ? 'text-white/80 hover:text-white' : 'text-mudo hover:text-tinta')}>Não tenho código</a>
          <span className={escuro ? 'text-white/40' : 'text-fio'}>·</span>
          <a href="#" className={'font-bold underline underline-offset-4 ' + (escuro ? 'text-ambar' : 'text-tinta')}>Cadastrar meu livro</a>
        </div>
      )}
    </form>
  )
}

const Dica = ({ escuro }) => <p className={'text-[12px] mt-1 ' + (escuro ? 'text-white/55' : 'text-mudo')}>6 números, enviados pelo WhatsApp quando o cadastro é liberado.</p>

